package com.sakib.portebo.ui;
import android.os.Bundle;import android.text.Editable;import android.text.TextWatcher;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.EditText;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.appcompat.app.AlertDialog;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButton;import com.sakib.portebo.R;import com.sakib.portebo.data.AppTierManager;import com.sakib.portebo.data.PrefsManager;import com.sakib.portebo.model.AppItem;import com.sakib.portebo.security.ParentControlManager;import com.sakib.portebo.ui.adapter.AppPickerAdapter;import com.sakib.portebo.ui.adapter.AppTierAdapter;import java.util.List;
public class AppTiersFragment extends Fragment {private RecyclerView list;private AppTierAdapter adapter;private TextView all,w,g,b;private int whiteCount,greyCount,blackCount;private EditText search,greyWarning,blackWarning;private AppItem.Tier selectedTier;private View addAppButton,saveWarningsButton;
 @Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View r=i.inflate(R.layout.fragment_app_tiers,c,false);list=r.findViewById(R.id.rvAppTiers);all=r.findViewById(R.id.tvCountAll);w=r.findViewById(R.id.tvCountWhitelist);g=r.findViewById(R.id.tvCountGreylist);b=r.findViewById(R.id.tvCountBlacklist);search=r.findViewById(R.id.etSearchApps);greyWarning=r.findViewById(R.id.etGreylistWarning);blackWarning=r.findViewById(R.id.etBlacklistWarning);greyWarning.setText(PrefsManager.getGreylistWarning());blackWarning.setText(PrefsManager.getBlacklistWarning());saveWarningsButton=r.findViewById(R.id.btnSaveWarnings);addAppButton=r.findViewById(R.id.btnAddNewApp);saveWarningsButton.setOnClickListener(v->{if(!ParentControlManager.requireEditAccess(requireContext()))return;PrefsManager.saveGreylistWarning(greyWarning.getText().toString());PrefsManager.saveBlacklistWarning(blackWarning.getText().toString());Toast.makeText(requireContext(),"মেসেজ সেভ হয়েছে।",Toast.LENGTH_SHORT).show();});addAppButton.setOnClickListener(v->{if(ParentControlManager.requireEditAccess(requireContext()))showPicker();});list.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new AppTierAdapter(requireContext(),AppTierManager.getAllApps(),this::onTierChanged);list.setAdapter(adapter);all.setOnClickListener(v->selectTier(null));w.setOnClickListener(v->selectTier(AppItem.Tier.WHITELIST));g.setOnClickListener(v->selectTier(AppItem.Tier.GREYLIST));b.setOnClickListener(v->selectTier(AppItem.Tier.BLACKLIST));all.setContentDescription("সব অ্যাপ দেখাও");w.setContentDescription("খোলা অ্যাপ দেখাও");g.setContentDescription("টাইমার অ্যাপ দেখাও");b.setContentDescription("ব্লক অ্যাপ দেখাও");search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){adapter.filter(s.toString());}public void afterTextChanged(Editable e){}});count();applyAccess();return r;}
 public void refreshAccess(){if(isAdded())applyAccess();}
 private void applyAccess(){if(!isAdded())return;boolean edit=ParentControlManager.canEdit(requireContext());if(saveWarningsButton!=null){saveWarningsButton.setEnabled(edit);saveWarningsButton.setAlpha(edit?1f:.45f);}if(addAppButton!=null){addAppButton.setEnabled(edit);addAppButton.setAlpha(edit?1f:.45f);}if(greyWarning!=null)greyWarning.setEnabled(edit);if(blackWarning!=null)blackWarning.setEnabled(edit);if(adapter!=null)adapter.setEditingEnabled(edit);}
 private void selectTier(AppItem.Tier tier){selectedTier=tier;adapter.setTierFilter(tier);drawCounts(AppTierManager.getAllApps().size());}
 private void count(){List<AppItem>a=AppTierManager.getAllApps();whiteCount=0;greyCount=0;blackCount=0;for(AppItem q:a){if(q.getTier()==AppItem.Tier.WHITELIST)whiteCount++;else if(q.getTier()==AppItem.Tier.GREYLIST)greyCount++;else blackCount++;}drawCounts(a.size());}
 private void onTierChanged(AppItem.Tier oldTier,AppItem.Tier newTier){if(oldTier==AppItem.Tier.WHITELIST)whiteCount--;else if(oldTier==AppItem.Tier.GREYLIST)greyCount--;else blackCount--;if(newTier==AppItem.Tier.WHITELIST)whiteCount++;else if(newTier==AppItem.Tier.GREYLIST)greyCount++;else blackCount++;adapter.setTierFilter(selectedTier);drawCounts(AppTierManager.getAllApps().size());}
 private void drawCounts(int total){all.setText("সব · "+total);w.setText("খোলা · "+whiteCount);g.setText("টাইমার · "+greyCount);b.setText("ব্লক · "+blackCount);}
 private void showPicker(){if(!ParentControlManager.requireEditAccess(requireContext()))return;View v=getLayoutInflater().inflate(R.layout.dialog_app_picker,null);RecyclerView rv=v.findViewById(R.id.rvPickerApps);rv.setLayoutManager(new LinearLayoutManager(requireContext()));AppPickerAdapter a=new AppPickerAdapter(requireContext(),(p,n)->{if(!ParentControlManager.requireEditAccess(requireContext()))return;AppTierManager.addApp(requireContext(),p,n);adapter.updateData(AppTierManager.getAllApps());count();});rv.setAdapter(a);AlertDialog d=new AlertDialog.Builder(requireContext()).setView(v).create();v.findViewById(R.id.btnDonePicker).setOnClickListener(x->d.dismiss());d.show();}
}
